import React, { useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import backgroundImage from "../Img/order5.jpg"; // Corrected import path

const AddOrder = () => {
  const [orderData, setOrderData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    phoneNumber: "",
    address: "",
    city: "",
    orderId: "",
    specialInstructions: "",
    pickupTime: "",
    orderStatus: "",
  });

  const navigate = useNavigate();

  const handleChange = (e) => {
    setOrderData({ ...orderData, [e.target.name]: e.target.value });
  };

  const sendData = (e) => {
    e.preventDefault();

    axios
      .post("http://localhost:5555/orders/add", orderData)
      .then(() => {
        alert("Order Added");
        setOrderData({
          firstName: "",
          lastName: "",
          email: "",
          phoneNumber: "",
          address: "",
          city: "",
          orderId: "",
          specialInstructions: "",
          pickupTime: "",
          orderStatus: "",
        });
        navigate("/all-orders");
      })
      .catch((err) => {
        alert(err);
      });
  };

  return (
    <div
      style={{
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        minHeight: "100vh",
        backgroundColor: "#f0f0f0",
        backgroundImage: `url(${backgroundImage})`,
        backgroundSize: "cover",
        backgroundRepeat: "no-repeat",
        backgroundBlendMode: "lighten",
      }}
    >
      <div
        style={{
          backgroundColor: "rgba(255, 255, 255, 0.8)",
          padding: "20px",
          borderRadius: "10px",
          boxShadow: "0px 4px 10px rgba(0, 0, 0, 0.1)",
          width: "100%",
          maxWidth: "600px",
          boxSizing: "border-box",
        }}
      >
        <form onSubmit={sendData} style={{ width: "100%" }}>
          {["firstName", "lastName", "email", "phoneNumber", "address", "city", "orderId", "specialInstructions", "pickupTime", "orderStatus"].map((field) => (
            <div key={field} style={{ marginBottom: "15px" }}>
              <label htmlFor={field} style={{ display: "block", fontWeight: "bold" }}>{field.replace(/([A-Z])/g, " $1").trim()}</label>
              <input
                type="text"
                id={field}
                name={field}
                style={{ width: "100%", padding: "10px", border: "1px solid #ccc", borderRadius: "5px", boxSizing: "border-box" }}
                placeholder={`Enter ${field}`}
                value={orderData[field]}
                onChange={handleChange}
              />
            </div>
          ))}
          <button
            type="submit"
            style={{
              backgroundColor: "#b30000",
              color: "white",
              padding: "10px 20px",
              border: "none",
              borderRadius: "5px",
              cursor: "pointer",
              fontSize: "16px",
            }}
          >
            Submit
          </button>
        </form>
      </div>
    </div>
  );
};

export default AddOrder;
